date_default_timezone_set('Europe/Berlin');
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';
function invoiceViewH(string|int|float|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function invoiceViewText(string|null $text,array $values):string{$expanded=str_replace(array_keys($values),array_values($values),$text??'');return nl2br(invoiceViewH($expanded));}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Kein Zugriff.');}
$db=coachingDatabase();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$q=$db->prepare('SELECT r.*,k.vorname,k.nachname FROM coaching_rechnungen r INNER JOIN klienten k ON k.id=r.klient_id WHERE r.id=:id AND r.coach_benutzer_id=:coach AND k.benutzer_id=:owner');$q->execute(['id'=>$id,'coach'=>(int)$user['id'],'owner'=>(int)$user['id']]);$invoice=$q->fetch(PDO::FETCH_ASSOC);if(!$invoice){http_response_code(404);exit('Rechnung nicht gefunden.');}
$values=['{{coach_name}}'=>$invoice['absender_name'],'{{klient_name}}'=>$invoice['empfaenger_name'],'{{auftrag}}'=>$invoice['auftrag_titel'],'{{sitzungsdatum}}'=>date('d.m.Y H:i',strtotime($invoice['sitzung_beginn'])),'{{rechnungsnummer}}'=>$invoice['rechnungsnummer']??'Entwurf','{{rechnungsdatum}}'=>$invoice['rechnungsdatum']?date('d.m.Y',strtotime($invoice['rechnungsdatum'])):'','{{nettobetrag}}'=>number_format((float)$invoice['netto'],2,',','.'),'{{steuerbetrag}}'=>number_format((float)$invoice['steuerbetrag'],2,',','.'),'{{bruttobetrag}}'=>number_format((float)$invoice['brutto'],2,',','.')];
$fromAddress=(string)($invoice['absender_adresse']??'');$toAddress=(string)($invoice['empfaenger_adresse']??'');
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=invoiceViewH($invoice['rechnungsnummer']?:'Rechnungsentwurf')?></title><link rel="stylesheet" href="assets/layout.css"><style>
body{background:#f3f5f3;color:#24332d}.actions{max-width:850px;margin:20px auto;display:flex;gap:10px;flex-wrap:wrap}.button{background:#245c50;color:#fff;border:0;border-radius:8px;padding:10px 14px;text-decoration:none;font:inherit;cursor:pointer}.paper{max-width:850px;min-height:1050px;margin:20px auto 60px;padding:56px 60px;background:white;box-shadow:0 8px 32px #0001;box-sizing:border-box}.top{display:flex;justify-content:space-between;gap:24px}.logo{max-width:190px;max-height:90px;object-fit:contain}.party{white-space:pre-line;line-height:1.5}.address-grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin:55px 0 42px;font-size:14px}.small{font-size:12px;color:#67756f}.headline{display:flex;justify-content:space-between;align-items:start}.table{width:100%;border-collapse:collapse;margin:22px 0}.table th,.table td{padding:12px 8px;border-bottom:1px solid #dce5df;text-align:left}.num{text-align:right!important;white-space:nowrap}.totals{margin-left:auto;width:min(330px,100%)}.totals div{display:flex;justify-content:space-between;padding:5px 0}.totals .grand{font-size:20px;font-weight:700;border-top:2px solid #263831;margin-top:7px;padding-top:11px}.textblock{margin:25px 0;line-height:1.55;white-space:normal}.footer{border-top:1px solid #dce5df;margin-top:55px;padding-top:14px;font-size:12px;white-space:pre-line;color:#66736d}.status{color:#245c50;font-weight:700}@media(max-width:700px){.paper{margin:0;min-height:0;padding:28px 22px;box-shadow:none}.address-grid{margin:34px 0;gap:18px}.actions{padding:12px;box-sizing:border-box}}@media print{body{background:white}.actions{display:none}.paper{margin:0;max-width:none;min-height:0;box-shadow:none;padding:15mm 18mm}.status{display:none}@page{size:A4;margin:0}}
</style></head><body>
<div class="actions"><a class="button" href="invoices.php">← Rechnungsübersicht</a><?php if($invoice['status']==='entwurf'):?><a class="button" href="invoices.php?edit=<?=(int)$invoice['id']?>">Entwurf bearbeiten</a><?php endif;?><button class="button" onclick="window.print()">Drucken / als PDF speichern</button></div>
<main class="paper"><div class="top"><div><strong><?=invoiceViewH($invoice['absender_name'])?></strong><div class="small party"><?=invoiceViewH($fromAddress)?></div><div class="small"><?=invoiceViewH($invoice['absender_email']??'')?><?= $invoice['absender_telefon']?' · '.invoiceViewH($invoice['absender_telefon']):''?></div></div><?php if($invoice['logo_speicher_schluessel']):?><img class="logo" src="invoice-logo.php?id=<?=(int)$invoice['id']?>" alt="Logo"><?php endif;?></div>
