<table class="table"><thead><tr><th>Leistung</th><th>Datum</th><th>Dauer</th><th class="num">Netto</th></tr></thead><tbody><tr><td><?=invoiceViewH($invoice['leistungsbeschreibung'])?><div class="small">Auftrag: <?=invoiceViewH($invoice['auftrag_titel'])?></div></td><td><?=invoiceViewH(date('d.m.Y',strtotime($invoice['sitzung_beginn'])))?></td><td><?=(int)$invoice['dauer_minuten']?> Min.</td><td class="num"><?=number_format((float)$invoice['netto'],2,',','.')?> EUR</td></tr></tbody></table>
