<div class="textblock"><strong>Zahlung:</strong> <?= $invoice['zahlungsart']==='bar'?'Barzahlung':'Überweisung' ?><?php if($invoice['zahlungsart']==='ueberweisung'&&($invoice['bank_iban']||$invoice['bank_inhaber']||$invoice['bank_bic'])):?><br>Kontoinhaber: <?=invoiceViewH($invoice['bank_inhaber']??'')?> · IBAN: <?=invoiceViewH($invoice['bank_iban']??'')?><?= $invoice['bank_bic']?' · BIC: '.invoiceViewH($invoice['bank_bic']):''?><?php endif;?><?php if($invoice['status']==='bezahlt'&&$invoice['bezahlt_am']):?><br>Bezahlt am: <?=invoiceViewH(date('d.m.Y',strtotime($invoice['bezahlt_am'])))?><?php endif;?></div>
<div class="small"><?= $invoice['steuernummer']?'Steuernummer: '.invoiceViewH($invoice['steuernummer']):'' ?><?= $invoice['umsatzsteuer_id']?'<br>USt-ID: '.invoiceViewH($invoice['umsatzsteuer_id']):'' ?></div>
<?php if($invoice['fusszeile']):?><footer class="footer"><?=invoiceViewText($invoice['fusszeile'],$values)?></footer><?php endif;?></main></body></html>